from PIL import JpegImageFile

class JPEGSerializer:
    def serialize(self, item: Image) -> Tuple[bytes, Optional[str]]:
        if not isinstance(item, JpegImageFile):
            raise TypeError("The item is not a supported image type.")

        if not hasattr(item, 'filename'):
            raise ValueError("JpegImageFile must have a filename attribute.")

        if os.path.exists(item.filename):
            with open(item.filename, 'rb') as file:
                return file.read(), None
        else:
            with BytesIO() as bio:
                item.save(bio, format="JPEG", quality=100)
                return bio.getvalue(), None
